-- Reference schema; the canonical schema is maintained by SQLAlchemy in models/models.py.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS admins (id INTEGER PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(500), image VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, description TEXT, price NUMERIC(10,2) NOT NULL, compare_at_price NUMERIC(10,2), stock INTEGER NOT NULL DEFAULT 0, sku VARCHAR(60) NOT NULL UNIQUE, image VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT 1, is_featured BOOLEAN NOT NULL DEFAULT 0, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS cart_items (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, quantity INTEGER NOT NULL, UNIQUE(customer_id, product_id));
CREATE TABLE IF NOT EXISTS shipping_rates (id INTEGER PRIMARY KEY, governorate VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL DEFAULT '', area VARCHAR(100) NOT NULL DEFAULT '', fee NUMERIC(10,2) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT 1, UNIQUE(governorate, city, area));
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, order_number VARCHAR(32) NOT NULL UNIQUE, customer_id INTEGER REFERENCES customers(id) ON DELETE SET NULL, customer_name VARCHAR(120) NOT NULL, email VARCHAR(255), phone VARCHAR(30) NOT NULL, governorate VARCHAR(100) NOT NULL, city VARCHAR(100), area VARCHAR(100), address VARCHAR(500) NOT NULL, notes VARCHAR(1000), subtotal NUMERIC(10,2) NOT NULL, shipping_fee NUMERIC(10,2) NOT NULL, total NUMERIC(10,2) NOT NULL, payment_method VARCHAR(20) NOT NULL CHECK(payment_method='cod'), status VARCHAR(24) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id) ON DELETE SET NULL, product_name VARCHAR(160) NOT NULL, sku VARCHAR(60) NOT NULL, unit_price NUMERIC(10,2) NOT NULL, quantity INTEGER NOT NULL, line_total NUMERIC(10,2) NOT NULL);
